/**
 * @summary Send a chat message and get AI response
 */
export const getSendChatMessageUrl = (id: number) => {
  return `/api/sessions/${id}/chat`;
};

export const sendChatMessage = async (
  id: number,
  chatMessageBody: ChatMessageBody,
  options?: RequestInit,
): Promise<ChatResponse> => {
  return customFetch<ChatResponse>(getSendChatMessageUrl(id), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(chatMessageBody),
  });
};

export const getSendChatMessageMutationOptions = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof sendChatMessage>>,
    TError,
    { id: number; data: BodyType<ChatMessageBody> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof sendChatMessage>>,
  TError,
  { id: number; data: BodyType<ChatMessageBody> },
  TContext
> => {
  const mutationKey = ["sendChatMessage"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof sendChatMessage>>,
    { id: number; data: BodyType<ChatMessageBody> }
  > = (props) => {
    const { id, data } = props ?? {};

    return sendChatMessage(id, data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type SendChatMessageMutationResult = NonNullable<
  Awaited<ReturnType<typeof sendChatMessage>>
>;
export type SendChatMessageMutationBody = BodyType<ChatMessageBody>;
export type SendChatMessageMutationError = ErrorType<unknown>;

/**
 * @summary Send a chat message and get AI response
 */
export const useSendChatMessage = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof sendChatMessage>>,
    TError,
    { id: number; data: BodyType<ChatMessageBody> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationResult<
  Awaited<ReturnType<typeof sendChatMessage>>,
  TError,
  { id: number; data: BodyType<ChatMessageBody> },
  TContext
> => {
  return useMutation(getSendChatMessageMutationOptions(options));
};

